192: fn decode_block_overrides(
193:     snapshot: &crate::module_bindings::GatewayChunkSnapshot,
194:     chunk_x: i32,
195:     chunk_z: i32,
196: ) -> io::Result<std::collections::BTreeMap<(i32, i32, i32), i32>> {
197:     if snapshot.chunk_x != chunk_x
198:         || snapshot.chunk_z != chunk_z
199:         || snapshot.encoded_overrides.len() > 2048
200:         || !snapshot.encoded_overrides.len().is_multiple_of(16)
201:     {
202:         return Err(invalid_data("invalid bounded chunk override snapshot"));
203:     }
204:     let mut rows = std::collections::BTreeMap::new();
205:     let (chunks, _) = snapshot.encoded_overrides.as_chunks::<16>();
206:     for bytes in chunks {
207:         let x = i32::from_le_bytes(bytes[0..4].try_into().unwrap());
208:         let y = i32::from_le_bytes(bytes[4..8].try_into().unwrap());
209:         let z = i32::from_le_bytes(bytes[8..12].try_into().unwrap());
210:         let state = i32::from_le_bytes(bytes[12..16].try_into().unwrap());
211:         if x.div_euclid(16) != chunk_x
212:             || z.div_euclid(16) != chunk_z
213:             || !(-64..=319).contains(&y)
214:             || !(0..=u32::MAX as i64).contains(&i64::from(state))
215:             || rows.insert((x, y, z), state).is_some()
216:         {
217:             return Err(invalid_data(
218:                 "invalid coordinate in chunk override snapshot",
219:             ));
220:         }
221:     }
222:     Ok(rows)
223: }
